//! First Rust-CUDA pipeline primitives corresponding to `pipe_add_n`,
//! `silu_mul`, and `pipe_rows_add` in `c/backend_cuda.cu`.

#![recursion_limit = "256"]

#[allow(dead_code)] // wired into model dispatch after the current CUDA smoke phase
mod cublas_exact;
mod safetensors;
mod v4_certified;
mod v4_chat;
